using GraphApi.Models.SGR.RecuperacionPassword;namespace GraphApi.Services.SGR.RecuperacionPassword{    /// <summary>    /// Define las operaciones de negocio y persistencia para RecuperacionPasswords.    /// </summary>    public interface IRecuperacionPasswordService    {        /// <summary>        /// Obtiene la lista de RecuperacionPasswords con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadRecuperacionPassword>> GetRecuperacionPasswords(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de RecuperacionPasswords con filtros opcionales.        /// </summary>        /// <param name="recuperacionPasswordID">Filtro opcional para RecuperacionPasswordID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="token">Filtro opcional para Token.</param>        /// <param name="fechaGeneracion">Filtro opcional para FechaGeneracion.</param>        /// <param name="fechaExpiracion">Filtro opcional para FechaExpiracion.</param>        /// <param name="usado">Filtro opcional para Usado.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetRecuperacionPasswordsDynamic(            int? recuperacionPasswordID,            int? usuarioID,            string? token,            DateTime? fechaGeneracion,            DateTime? fechaExpiracion,            bool? usado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo RecuperacionPassword.        /// </summary>        /// <param name="objInput">Datos para crear el RecuperacionPassword.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRecuperacionPassword> CreateRecuperacionPassword(            clCreateRecuperacionPassword objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un RecuperacionPassword.        /// </summary>        /// <param name="objInput">Datos para actualizar el RecuperacionPassword, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadRecuperacionPassword?> UpdateRecuperacionPassword(            clUpdateRecuperacionPassword objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un RecuperacionPassword por su ID.        /// </summary>        /// <param name="nRecuperacionPasswordID">ID del RecuperacionPassword a eliminar.</param>        Task<bool> DeleteRecuperacionPassword(int nRecuperacionPasswordID);    }}